CREATE OR REPLACE PROCEDURE registrar_venta(p_cliente INT, p_producto INT, p_cantidad INT, p_metodo VARCHAR)
LANGUAGE plpgsql AS $$
DECLARE
  v_precio DECIMAL;
  v_stock INT;
  v_venta INT;
BEGIN
  SELECT precio, stock INTO v_precio, v_stock FROM productos WHERE id = p_producto;
  IF v_precio IS NULL THEN
    RAISE EXCEPTION 'El producto % no existe', p_producto;
  END IF;
  IF v_stock < p_cantidad THEN
    RAISE EXCEPTION 'Stock insuficiente: hay % y pediste %', v_stock, p_cantidad;
  END IF;
  INSERT INTO ventas (cliente_id, metodo_pago, total)
  VALUES (p_cliente, p_metodo, v_precio * p_cantidad) RETURNING id INTO v_venta;
  INSERT INTO detalle_ventas (venta_id, producto_id, cantidad, precio_unitario, subtotal)
  VALUES (v_venta, p_producto, p_cantidad, v_precio, v_precio * p_cantidad);
  UPDATE productos SET stock = stock - p_cantidad WHERE id = p_producto;
END; $$;

